SELECT client_accounts.id, client_accounts.display_name AS displayName, CASE WHEN client_accounts.phone IS NULL THEN NULL ELSE CONCAT(LEFT(client_accounts.phone, 3), '***', RIGHT(client_accounts.phone, 3)) END AS maskedPhone, COUNT(sales_sessions.id) AS sessionCount, MAX(sales_sessions.created_at) AS lastVisitedAt, COALESCE(SUM(payments.amount), 0) AS totalPaid FROM client_accounts LEFT JOIN sales_sessions ON sales_sessions.client_account_id = client_accounts.id AND sales_sessions.store_id = client_accounts.store_id AND sales_sessions.created_at >= #{from} AND sales_sessions.created_at < #{to} LEFT JOIN payments ON payments.sales_session_id = sales_sessions.id AND payments.status = 'PAID' WHERE client_accounts.store_id = #{storeId} AND sales_sessions.id IS NOT NULL GROUP BY client_accounts.id, client_accounts.display_name, client_accounts.phone ORDER BY
totalPaid DESC, totalPaid ASC, sessionCount DESC, sessionCount ASC,
lastVisitedAt DESC, client_accounts.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT audit_logs.id, audit_logs.action, audit_logs.entity_type AS entityType, audit_logs.entity_id AS entityId,
       audit_logs.entity_name AS entityName, audit_logs.actor_name AS actorName, audit_logs.description, audit_logs.created_at AS createdAt
FROM audit_logs WHERE audit_logs.store_id=#{storeId}
ORDER BY audit_logs.created_at DESC, audit_logs.id DESC LIMIT #{limit} OFFSET #{offset}
